import React, { useState } from 'react';

const TradePanel = ({ symbol, price, onBuy, onSell, loading }) => {
    const [quantity, setQuantity] = useState(1);
    const [tradeType, setTradeType] = useState('BUY');
    const [orderType, setOrderType] = useState('LIMIT');
    const [limitPrice, setLimitPrice] = useState('');
    const [tradeMode, setTradeMode] = useState('DELIVERY'); // DELIVERY, INTRADAY, MTF

    const totalCost = price ? price * quantity : 0;

    return (
        <div style={{
            background: '#141b2b',
            padding: '20px',
            borderRadius: '10px',
            border: '1px solid #2a3a5c'
        }}>
            {/* Buy/Sell Toggle */}
            <div style={{ display: 'flex', gap: '10px', marginBottom: '15px' }}>
                <button
                    onClick={() => setTradeType('BUY')}
                    style={{
                        flex: 1,
                        padding: '10px',
                        background: tradeType === 'BUY' ? '#4CAF50' : '#1a2332',
                        color: 'white',
                        border: tradeType === 'BUY' ? '2px solid #4CAF50' : '1px solid #2a3a5c',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        fontWeight: 'bold',
                        fontSize: '16px'
                    }}
                >
                    BUY
                </button>
                <button
                    onClick={() => setTradeType('SELL')}
                    style={{
                        flex: 1,
                        padding: '10px',
                        background: tradeType === 'SELL' ? '#dc3545' : '#1a2332',
                        color: 'white',
                        border: tradeType === 'SELL' ? '2px solid #dc3545' : '1px solid #2a3a5c',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        fontWeight: 'bold',
                        fontSize: '16px'
                    }}
                >
                    SELL
                </button>
            </div>

            {/* Trade Mode */}
            <div style={{ 
                display: 'flex', 
                gap: '8px', 
                marginBottom: '15px',
                borderBottom: '1px solid #2a3a5c',
                paddingBottom: '10px'
            }}>
                {['DELIVERY', 'INTRADAY', 'MTF 4.12x'].map((mode) => (
                    <button
                        key={mode}
                        onClick={() => setTradeMode(mode)}
                        style={{
                            padding: '4px 12px',
                            background: tradeMode === mode ? '#2a3a5c' : 'transparent',
                            color: tradeMode === mode ? '#e0e6ed' : '#8a9bb5',
                            border: tradeMode === mode ? '1px solid #4CAF50' : '1px solid transparent',
                            borderRadius: '4px',
                            cursor: 'pointer',
                            fontSize: '12px'
                        }}
                    >
                        {mode}
                    </button>
                ))}
            </div>

            {/* Quantity and Price */}
            <div style={{ display: 'flex', gap: '15px', marginBottom: '15px' }}>
                <div style={{ flex: 1 }}>
                    <label style={{ display: 'block', marginBottom: '5px', color: '#8a9bb5', fontSize: '13px' }}>
                        Qty
                    </label>
                    <input
                        type="number"
                        min="1"
                        value={quantity}
                        onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value) || 1))}
                        style={{
                            width: '100%',
                            padding: '8px 12px',
                            background: '#1a2332',
                            border: '1px solid #2a3a5c',
                            borderRadius: '6px',
                            color: 'white',
                            fontSize: '14px'
                        }}
                    />
                </div>
                <div style={{ flex: 2 }}>
                    <label style={{ display: 'block', marginBottom: '5px', color: '#8a9bb5', fontSize: '13px' }}>
                        Price
                    </label>
                    <select
                        value={orderType}
                        onChange={(e) => setOrderType(e.target.value)}
                        style={{
                            width: '100%',
                            padding: '8px 12px',
                            background: '#1a2332',
                            border: '1px solid #2a3a5c',
                            borderRadius: '6px',
                            color: 'white',
                            fontSize: '14px'
                        }}
                    >
                        <option value="LIMIT">Limit</option>
                        <option value="MARKET">Market</option>
                        <option value="SL">Stop Loss</option>
                    </select>
                </div>
            </div>

            {/* Limit Price Input (if LIMIT selected) */}
            {orderType === 'LIMIT' && (
                <div style={{ marginBottom: '15px' }}>
                    <label style={{ display: 'block', marginBottom: '5px', color: '#8a9bb5', fontSize: '13px' }}>
                        Limit Price
                    </label>
                    <input
                        type="number"
                        placeholder={price ? `₹${price.toFixed(2)}` : 'Enter price'}
                        value={limitPrice}
                        onChange={(e) => setLimitPrice(e.target.value)}
                        style={{
                            width: '100%',
                            padding: '8px 12px',
                            background: '#1a2332',
                            border: '1px solid #2a3a5c',
                            borderRadius: '6px',
                            color: 'white',
                            fontSize: '14px'
                        }}
                    />
                </div>
            )}

            {/* Balance and Total */}
            <div style={{ 
                display: 'flex', 
                justifyContent: 'space-between',
                padding: '10px',
                background: '#1a2332',
                borderRadius: '6px',
                marginBottom: '15px'
            }}>
                <span style={{ color: '#8a9bb5' }}>Balance: ₹29,281</span>
                <span style={{ color: '#8a9bb5' }}>
                    Approx req.: <span style={{ color: '#e0e6ed' }}>₹{totalCost.toFixed(0)}</span>
                </span>
            </div>

            {/* Buy Button */}
            <button
                onClick={() => {
                    if (tradeType === 'BUY') {
                        onBuy(quantity);
                    } else {
                        onSell(quantity);
                    }
                }}
                disabled={loading || !price}
                style={{
                    width: '100%',
                    padding: '14px',
                    background: tradeType === 'BUY' ? '#4CAF50' : '#dc3545',
                    color: 'white',
                    border: 'none',
                    borderRadius: '6px',
                    fontSize: '18px',
                    fontWeight: 'bold',
                    cursor: 'pointer',
                    opacity: loading || !price ? 0.5 : 1,
                    transition: 'all 0.3s'
                }}
            >
                {loading ? 'Processing...' : tradeType}
            </button>

            {!price && (
                <p style={{ color: '#8a9bb5', textAlign: 'center', marginTop: '10px', fontSize: '14px' }}>
                    🔍 Search for a stock to start trading
                </p>
            )}
        </div>
    );
};

export default TradePanel;
